import React from 'react';
import { APIProvider, Map, AdvancedMarker } from '@vis.gl/react-google-maps';

const Mapa = () => {
  const API_KEY = 'AIzaSyDjxmuJz8jqAl3hGWk5iinFc1u7ezRaTjU';
  const MAP_ID = 'c86529b84ea49068e01bcd79'; // <--- O ID que você criou no Google Cloud

  return (
    <div style={{ display: 'flex', height: '100vh' }}>
      {/* Sua Sidebar aqui */}
      <aside style={{ width: '300px', zIndex: 10 }}>
        <h2>Cadastro</h2>
      </aside>

      {/* O Mapa com seu Estilo Personalizado */}
      <main style={{ flex: 1 }}>
        <APIProvider apiKey={API_KEY}>
          <Map
            defaultCenter={{ lat: -15.78, lng: -47.92 }}
            defaultZoom={13}
            mapId={MAP_ID} // <--- É aqui que a mágica acontece!
            gestureHandling={'greedy'}
            disableDefaultUI={false}
          >
            <AdvancedMarker position={{ lat: -15.78, lng: -47.92 }} />
          </Map>
        </APIProvider>
      </main>
    </div>
  );
};

export default Mapa;
